INSERT INTO categories (id, name, description, image_url, active) VALUES
(6, 'Mỹ phẩm & Làm đẹp', 'Son môi, kem dưỡng da, serum và mỹ phẩm chính hãng', 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=600&auto=format&fit=crop&q=80', TRUE),
(7, 'Đồng hồ & Phụ kiện', 'Đồng hồ nam nữ, kính mắt và trang sức thời thượng', 'https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=600&auto=format&fit=crop&q=80', TRUE),
(8, 'Mẹ & Bé', 'Tã bỉm, sữa công thức, xe đẩy và đồ chơi trẻ em', 'https://images.unsplash.com/photo-1515488042361-ee00e0ddd4e4?w=600&auto=format&fit=crop&q=80', TRUE)
INSERT INTO products (id, name, description, price, image_url, category_id, stock_quantity, active) VALUES
(15, 'Áo sơ mi nam công sở Oxford cao cấp', 'Chất liệu cotton Oxford dày dặn, chống nhăn tốt, thấm hút mồ hôi tối ưu. Form regular fit thanh lịch phù hợp môi trường văn phòng.', 380000, 'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=600&auto=format&fit=crop&q=80', 1, 45, TRUE),
(16, 'Váy hoa nhí vintage tay bồng dáng xòe', 'Váy hoa nhí phong cách vintage nhẹ nhàng, chất voan tơ mềm mại thoáng mát, có lớp lót kín đáo, tôn dáng phái đẹp trong mọi sự kiện.', 320000, 'https://images.unsplash.com/photo-1572804013309-59a88b7e92f1?w=600&auto=format&fit=crop&q=80', 1, 35, TRUE),
(17, 'Quần tây âu nam ống suông Hàn Quốc', 'Quần tây vải tuyết mưa co giãn nhẹ, đường ly sắc nét đứng form, phối cùng giày tây hoặc sneaker đều tạo nét lịch lãm hiện đại.', 420000, 'https://images.unsplash.com/photo-1473966968600-fa801b869a1a?w=600&auto=format&fit=crop&q=80', 1, 50, TRUE),
(18, 'Áo len cổ lọ dệt kim giữ nhiệt mùa đông', 'Sợi len dệt kim siêu mịn không gây ngứa ráp, cổ lọ ôm vừa vặn giữ ấm cổ, màu sắc trung tính dễ dàng phối layer cùng áo măng tô.', 350000, 'https://images.unsplash.com/photo-1576871337632-b9aef4c17ab9?w=600&auto=format&fit=crop&q=80', 1, 28, TRUE),
(19, 'Áo polo nam phối bo viền thể thao thoáng khí', 'Vải pique cá sấu thấm hút vượt trội, cổ dệt jacquard cao cấp, giữ phom dáng chuẩn suốt ngày dài vận động.', 260000, 'https://images.unsplash.com/photo-1625910513413-7e61e05d0e2e?w=600&auto=format&fit=crop&q=80', 1, 60, TRUE),
(20, 'Chân váy chữ A lưng cao phong cách thanh lịch', 'Thiết kế chữ A che khuyết điểm hông, chất vải dạ tweed dệt kim kim tuyến sang trọng, cạp cao tôn chiều cao cơ thể.', 280000, 'https://images.unsplash.com/photo-1583496661160-fb5886a0aaaa?w=600&auto=format&fit=crop&q=80', 1, 40, TRUE),
(21, 'Áo blazer nữ form rộng chuẩn Hàn Quốc', 'Blazer 2 lớp đệm vai nhẹ tạo form đứng thanh thoát, màu be pastel thời thượng thích hợp mặc đi làm lẫn dạo phố cuối tuần.', 650000, 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=600&auto=format&fit=crop&q=80', 1, 22, TRUE),
(22, 'Áo khoác da biker nam lót dù cao cấp', 'Da PU xử lý công nghệ cao bền bỉ chống nổ da, khóa kéo kim loại chống gỉ phong cách môtô khỏe khoắn và nam tính.', 890000, 'https://images.unsplash.com/photo-1551028719-00167b16eac5?w=600&auto=format&fit=crop&q=80', 1, 15, TRUE),
(23, 'Quần short kaki nam co giãn năng động', 'Kaki cotton thun co giãn 4 chiều, túi sâu tiện lợi để điện thoại ví tiền, thoáng mát lý tưởng cho ngày hè năng động.', 220000, 'https://images.unsplash.com/photo-1591195853828-11db59a44f6b?w=600&auto=format&fit=crop&q=80', 1, 55, TRUE),
(24, 'Giày sneaker trắng cổ thấp da PU cao cấp', 'Thiết kế tối giản basic kinh điển, đế cao su lưu hóa bền bỉ êm chân, lót đệm bọt khí chống hôi chân hiệu quả.', 590000, 'https://images.unsplash.com/photo-1549298916-b41d501d3772?w=600&auto=format&fit=crop&q=80', 1, 30, TRUE),
(25, 'Giày cao gót mũi nhọn 7cm nữ tính sang trọng', 'Gót thanh 7cm êm ái chống dốc chân, mũi nhọn thanh thoát kéo dài đôi chân, đệm lót 3D nâng đỡ gót hồng thoải mái di chuyển.', 480000, 'https://images.unsplash.com/photo-1543163521-1bf539c55dd2?w=600&auto=format&fit=crop&q=80', 1, 25, TRUE),
(26, 'Thắt lưng nam da bò thật khóa tự động', 'Mặt khóa hợp kim titan phay xước chống xước, dây da bò nguyên tấm 2 lớp mềm dẻo không gãy gập, khóa ray trượt tiện lợi.', 290000, 'https://images.unsplash.com/photo-1624222247344-550fb60583dc?w=600&auto=format&fit=crop&q=80', 1, 40, TRUE),
(27, 'Túi xách da nữ kẹp nách phong cách retro', 'Form túi hobo kẹp nách thời thượng, da nhân tạo tráng gương bóng nhẹ, ngăn chứa rộng rãi đựng vừa son, điện thoại và ví ngắn.', 450000, 'https://images.unsplash.com/photo-1584917865442-de89df76afd3?w=600&auto=format&fit=crop&q=80', 1, 32, TRUE),
(28, 'iPhone 15 Pro Max 256GB Titan Tự Nhiên', 'Khung viền Titan siêu nhẹ và bền bỉ, chip A17 Pro đỉnh cao đồ họa ray tracing, cụm 3 camera 48MP zoom quang học 5x sắc nét.', 29990000, 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=600&auto=format&fit=crop&q=80', 2, 12, TRUE),
(29, 'Samsung Galaxy S24 Ultra 512GB AI Phone', 'Màn hình Dynamic AMOLED 2X 120Hz phẳng viền titan, tích hợp bút S-Pen quyền năng, trợ lý Galaxy AI thông minh hàng đầu.', 26490000, 'https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=600&auto=format&fit=crop&q=80', 2, 10, TRUE),
(30, 'MacBook Air M2 13.6 inch 8GB/256GB', 'Thiết kế siêu mỏng nhẹ chỉ 1.24kg, thời lượng pin ấn tượng lên đến 18 tiếng, màn hình Liquid Retina 500 nits sống động rực rỡ.', 23890000, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=600&auto=format&fit=crop&q=80', 2, 8, TRUE),
(31, 'iPad Air 5 10.9 inch M1 Wi-Fi 64GB', 'Hiệu năng bứt phá với vi xử lý Apple M1 8 nhân, hỗ trợ Apple Pencil 2 và bàn phím Magic Keyboard, camera trước Ultra Wide Center Stage.', 14290000, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=600&auto=format&fit=crop&q=80', 2, 15, TRUE),
(32, 'Tai nghe chống ồn Sony WH-1000XM5', 'Công nghệ chống ồn hàng đầu thế giới với bộ xử lý kép V1/QN1, 8 micro thu âm, chất âm Hi-Res Audio không dây LDAC đỉnh cao.', 7490000, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', 2, 18, TRUE),
(33, 'Tai nghe Apple AirPods Pro 2 MagSafe USB-C', 'Chống ồn chủ động gấp 2 lần, chế độ Xuyên Âm thích ứng Adaptive Audio, chuẩn sạc Type-C tiện lợi và hộp sạc chống bụi nước IP54.', 5390000, 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?w=600&auto=format&fit=crop&q=80', 2, 25, TRUE),
(34, 'Loa Bluetooth Marshall Emberton II chống nước', 'Âm thanh 360 độ True Stereophonic sống động, pin trâu hơn 30 giờ chơi nhạc liên tục, chuẩn kháng nước bụi IP67 bền bỉ ngoài trời.', 3850000, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=600&auto=format&fit=crop&q=80', 2, 20, TRUE),
(35, 'Màn hình Dell UltraSharp 27 inch 4K IPS U2723QE', 'Tấm nền IPS Black độ tương phản 2000:1 chân thực, độ phân giải 4K UHD 3840x2160, độ phủ màu 98% DCI-P3, cổng Type-C 90W PD.', 11500000, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=600&auto=format&fit=crop&q=80', 2, 14, TRUE),
(36, 'Chuột không dây công thái học Logitech MX Master 3S', 'Cuộn siêu tốc MagSpeed điện từ 1000 dòng/giây, nút bấm Quiet Clicks giảm 90% tiếng ồn, cảm biến 8000 DPI di chuyển trên mọi bề mặt kể cả kính.', 2290000, 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=600&auto=format&fit=crop&q=80', 2, 30, TRUE),
(37, 'Bàn phím không dây cơ Keychron K2 Pro QMK/VIA', 'Layout 75% gọn gàng, hỗ trợ tùy biến macro qua phần mềm QMK/VIA, switch cơ Gateron G Pro mượt mà kèm đệm tiêu âm cao cấp.', 2190000, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=600&auto=format&fit=crop&q=80', 2, 22, TRUE),
(38, 'Đồng hồ thông minh Apple Watch Series 9 GPS 41mm', 'Tính năng chạm hai lần Double Tap độc đáo, màn hình sáng rực rỡ 2000 nits, cảm biến đo nhịp tim điện tâm đồ ECG và nồng độ oxy SpO2.', 8990000, 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=600&auto=format&fit=crop&q=80', 2, 16, TRUE),
(39, 'Vòng đeo tay thông minh Xiaomi Band 8 Active', 'Màn hình TFT 1.47 inch sắc nét, hơn 50 chế độ thể thao chuyên nghiệp, theo dõi giấc ngủ khoa học, thời lượng pin lên đến 14 ngày.', 590000, 'https://images.unsplash.com/photo-1575311373937-040b8e1fd5b6?w=600&auto=format&fit=crop&q=80', 2, 65, TRUE),
(40, 'Máy chơi game Sony PlayStation 5 Slim 1TB', 'Kích thước tinh gọn hơn 30%, ổ cứng SSD tốc độ siêu nhanh 1TB, đồ họa 4K 120fps HDR mượt mà cùng tay cầm phản hồi lực DualSense.', 12990000, 'https://images.unsplash.com/photo-1606813907291-d86efa9b94db?w=600&auto=format&fit=crop&q=80', 2, 7, TRUE),
(41, 'Ổ cứng SSD di động Samsung T7 Shield 1TB Type-C', 'Tốc độ đọc ghi tuần tự lên đến 1050MB/s, vỏ bọc cao su chống va đập từ độ cao 3 mét, chuẩn chống bụi nước IP65 an toàn dữ liệu.', 2650000, 'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?w=600&auto=format&fit=crop&q=80', 2, 35, TRUE),
(42, 'Sạc dự phòng Anker 737 PowerCore 24000mAh 140W', 'Công suất sạc nhanh hai chiều cực khủng 140W chuẩn PD 3.1 sạc được cả MacBook Pro 16 inch, màn hình kỹ thuật số hiển thị thông số thông minh.', 2890000, 'https://images.unsplash.com/photo-1609592426507-b35a39f60447?w=600&auto=format&fit=crop&q=80', 2, 28, TRUE),
(43, 'Máy ảnh Mirrorless Sony Alpha A6400 kèm Kit 16-50mm', 'Cảm biến APS-C 24.2MP Exmor CMOS, hệ thống lấy nét tự động 425 điểm theo pha Real-time Eye AF đỉnh cao, quay video 4K HDR sắc nét.', 19490000, 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=600&auto=format&fit=crop&q=80', 2, 6, TRUE),
(44, 'Nồi chiên không dầu Philips XXL 7.2L công nghệ Rapid Air', 'Dung tích lớn nướng gà nguyên con, công nghệ đảo nhiệt Rapid Air giảm 90% lượng dầu mỡ thừa, màn hình cảm ứng 16 chương trình cài sẵn.', 3490000, 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=600&auto=format&fit=crop&q=80', 3, 18, TRUE),
(45, 'Nồi áp suất điện tử Tefal Home Chef 6L', 'Công suất 1000W nấu nhanh hơn 80%, van xả áp tự động an toàn một chạm, lòng nồi dạng cầu niêu độc quyền truyền nhiệt đều khắp món ăn.', 1890000, 'https://images.unsplash.com/photo-1544233726-9f1d2b27be8b?w=600&auto=format&fit=crop&q=80', 3, 20, TRUE),
(46, 'Máy ép chậm Philips Viva Collection HR1889', 'Ống tiếp nguyên liệu cực lớn 70mm không cần cắt nhỏ hoa quả, công nghệ QuickClean rửa sạch nhanh chóng trong vòng 90 giây.', 2150000, 'https://images.unsplash.com/photo-1589365278144-c9e705f843ba?w=600&auto=format&fit=crop&q=80', 3, 15, TRUE),
(47, 'Máy xay sinh tố cầm tay Braun MultiQuick 7 1000W', 'Công nghệ lưỡi dao di động ActiveBlade nhuyễn mịn gấp 2 lần, điều khiển tốc độ thông minh SmartSpeed bằng lực bóp ngón tay.', 1690000, 'https://images.unsplash.com/photo-1570222094114-d054a817e56b?w=600&auto=format&fit=crop&q=80', 3, 25, TRUE),
(48, 'Robot hút bụi lau nhà Roborock Q Revo tự giặt giẻ', 'Lực hút 5500Pa cực mạnh, giẻ lau kép xoay 200 vòng/phút, trạm sạc đa năng tự giặt giẻ và sấy khô bằng khí nóng chống ẩm mốc.', 15990000, 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=600&auto=format&fit=crop&q=80', 3, 8, TRUE),
(49, 'Máy lọc không khí Xiaomi Smart Air Purifier 4 Pro', 'Lọc bụi mịn PM2.5, phấn hoa và lông thú cưng hiệu quả 99.97% với màng lọc HEPA 3in1, diện tích phủ phòng lớn lên tới 60m2.', 4290000, 'https://images.unsplash.com/photo-1585771724684-38269d6639fd?w=600&auto=format&fit=crop&q=80', 3, 16, TRUE),
(50, 'Máy hút bụi không dây Dyson V8 Absolute', 'Động cơ kỹ thuật số Dyson V8 quay 110000 vòng/phút, thời gian hoạt động 40 phút không sụt giảm công suất, đầu hút chuyên dụng cho lông thú.', 8490000, 'https://images.unsplash.com/photo-1558317374-067fb5f30001?w=600&auto=format&fit=crop&q=80', 3, 9, TRUE),
(51, 'Bộ nồi chảo chống dính 5 món Tefal Expertise', 'Chất liệu hợp kim nhôm đúc nguyên khối phủ lớp chống dính Titanium Excellence bền bỉ gấp 3 lần, điểm báo nhiệt Thermo-Signal chuẩn xác.', 2950000, 'https://images.unsplash.com/photo-1584990347449-3998f860f4eb?w=600&auto=format&fit=crop&q=80', 3, 22, TRUE),
(52, 'Ấm đun nước siêu tốc thủy tinh Lock&Lock 1.8L', 'Thân ấm thủy tinh Borosilicate chịu nhiệt cao trong suốt, đèn LED xanh dương phát sáng khi nấu, tự ngắt khi nước sôi bảo đảm an toàn.', 490000, 'https://images.unsplash.com/photo-1594212699903-ec8a3eca50f5?w=600&auto=format&fit=crop&q=80', 3, 40, TRUE),
(53, 'Bàn là hơi nước đứng Philips ComfortTouch Plus', 'Công suất 2000W phun hơi liên tục 40g/phút loại bỏ nếp nhăn nhanh chóng trên mọi loại vải lụa, cotton, khử mùi và diệt khuẩn 99.9%.', 2790000, 'https://images.unsplash.com/photo-1517677208171-0bc6725a3e60?w=600&auto=format&fit=crop&q=80', 3, 14, TRUE),
(54, 'Quạt điều hòa không khí Sunhouse SHD7746 45L', 'Bình chứa nước lớn 45L làm mát liên tục cả ngày, lưu lượng gió 5000 m3/h xua tan cái nóng oi bức mùa hè, tặng kèm 2 hộp đá khô.', 2590000, 'https://images.unsplash.com/photo-1585771724684-38269d6639fd?w=600&auto=format&fit=crop&q=80', 3, 12, TRUE),
(55, 'Đèn bàn LED chống cận Xiaomi Mijia Lite', 'Đạt chuẩn chiếu sáng quốc gia Class A, không có ánh sáng xanh gây hại mắt, chỉ số hoàn màu Ra90 chân thực, điều chỉnh 3 mức sáng.', 320000, 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=600&auto=format&fit=crop&q=80', 3, 50, TRUE),
(56, 'Máy làm sữa hạt đa năng Tefal Ultrablend Cook', '10 chương trình nấu tự động từ sữa hạt đậu nành, cháo dinh dưỡng đến súp nóng, cối thủy tinh chịu nhiệt kháng sốc va đập.', 3100000, 'https://images.unsplash.com/photo-1556911220-e15b29be8c8f?w=600&auto=format&fit=crop&q=80', 3, 11, TRUE),
(57, 'Máy tạo độ ẩm phun sương Deerma F628S', 'Dung tích 5L phun sương siêu mịn nano, khử trùng tia cực tím UV làm sạch nguồn nước trước khi khuếch tán, tích hợp khay tinh dầu thơm.', 390000, 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=600&auto=format&fit=crop&q=80', 3, 45, TRUE),
(58, 'Tâm Lý Học Về Tiền - Morgan Housel', 'Tuyệt phẩm giúp bạn hiểu rõ cách lòng tham, nỗi sợ và cái tôi chi phối các quyết định tài chính cá nhân trong cuộc sống thường nhật.', 155000, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=600&auto=format&fit=crop&q=80', 4, 50, TRUE),
(59, 'Nguyên Lý - Ray Dalio (Bản dịch chuẩn)', 'Những nguyên tắc sống và làm việc tạo nên thành công phi thường của huyền thoại đầu tư phố Wall Ray Dalio, nhà sáng lập Bridgewater Associates.', 320000, 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=600&auto=format&fit=crop&q=80', 4, 30, TRUE),
(60, 'Tư Duy Nhanh Và Chậm - Daniel Kahneman', 'Tác phẩm kinh điển đoạt giải Nobel Kinh tế khám phá hai hệ thống chi phối cách chúng ta suy nghĩ và đưa ra các phán đoán.', 190000, 'https://images.unsplash.com/photo-1495446815901-a7297e633e8d?w=600&auto=format&fit=crop&q=80', 4, 42, TRUE),
(61, 'Súng, Vi Trùng Và Thép - Jared Diamond', 'Giải Pulitzer lịch sử nhân loại giải mã định mệnh của các xã hội loài người qua yếu tố địa lý, dịch bệnh và công nghệ.', 220000, 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=600&auto=format&fit=crop&q=80', 4, 25, TRUE),
(62, 'Tuần Làm Việc 4 Giờ - Tim Ferriss', 'Bí quyết thoát khỏi cuộc đua vòng quay 9-to-5, tự động hóa thu nhập và tận hưởng cuộc sống tự do của một triệu phú thời đại số.', 145000, 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=600&auto=format&fit=crop&q=80', 4, 35, TRUE),
(63, 'Atomic Habits - Thay Đổi Tí Hon Hiệu Quả Bất Ngờ', 'Phương pháp khoa học xây dựng thói quen tốt và từ bỏ thói quen xấu qua quy luật 1% mỗi ngày của chuyên gia James Clear.', 160000, 'https://images.unsplash.com/photo-1532012164546-f432f2e3edd4?w=600&auto=format&fit=crop&q=80', 4, 60, TRUE),
