(109, 'Máy hút sữa điện đôi không dây Spectra Dual S', 'Động cơ kép hoạt động độc lập điều chỉnh lực hút từng bên ngực, 15 cấp độ hút và 5 cấp độ massage kích thích sữa non dồi dào.', 4150000, 'https://images.unsplash.com/photo-1555252333-9f8e92e65df9?w=600&auto=format&fit=crop&q=80', 8, 14, TRUE),
(110, 'Nôi cũi gỗ sồi tự nhiên đa năng cho bé', 'Gỗ sồi Nga tự nhiên phủ sơn gốc nước không mùi an toàn, chuyển đổi 3 nấc độ cao làm cũi chơi, giường ngủ ghép cạnh mẹ.', 3450000, 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?w=600&auto=format&fit=crop&q=80', 8, 8, TRUE),
(111, 'Bình sữa thủy tinh bọc silicone chống sặc Comotomo 250ml', 'Núm ti mô phỏng bầu ngực mẹ mềm mại cho bé dễ làm quen, 2 van thông khí thông minh ngăn ngừa đầy hơi nôn trớ hiệu quả.', 360000, 'https://images.unsplash.com/photo-1574169208507-84376144848b?w=600&auto=format&fit=crop&q=80', 8, 45, TRUE),
(112, 'Tã quần Bobby Mega Jumbo gói siêu đại size L 68 miếng', 'Lõi nén thần kỳ 3mm siêu mỏng thoáng, bề mặt 3000 lỗ thấm hút siêu tốc khóa chặt chất lỏng cho mông bé khô thoáng ngủ ngon cả đêm.', 320000, 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=600&auto=format&fit=crop&q=80', 8, 60, TRUE),
(113, 'Sữa bột Meiji số 9 nội địa Nhật 800g cho bé 1-3 tuổi', 'Vị thanh mát nhạt như sữa mẹ, bổ sung đầy đủ DHA, ARA, canxi và sắt giúp bé phát triển trí não thông minh và chiều cao vượt trội.', 480000, 'https://images.unsplash.com/photo-1550572017-edd951aa8f72?w=600&auto=format&fit=crop&q=80', 8, 50, TRUE),
(114, 'Đồ chơi lắp ráp trí tuệ LEGO Classic Thùng Gạch Lớn 790 chi tiết', 'Bộ đồ chơi sáng tạo 790 miếng ghép đa dạng màu sắc với mắt, bánh xe và cửa sổ kích thích trí tưởng tượng và tư duy logic của trẻ.', 1290000, 'https://images.unsplash.com/photo-1585366119957-e9730b6d0f60?w=600&auto=format&fit=crop&q=80', 8, 28, TRUE)
