-- =============================================================================
-- 03-seed-100-products.sql — Dữ liệu bổ sung 100 sản phẩm phong phú và thực tế
-- Phân bổ trên 8 danh mục sản phẩm (Thời trang, Điện tử, Gia dụng, Sách, Thể thao,
-- Mỹ phẩm & Làm đẹp, Đồng hồ & Phụ kiện, Mẹ & Bé)
-- =============================================================================

USE ecommerce_db;

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

-- 1. Thêm danh mục mới (nếu chưa có)
ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), image_url=VALUES(image_url);

-- 2. Thêm 100 sản phẩm mới
ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), price=VALUES(price), image_url=VALUES(image_url), category_id=VALUES(category_id), stock_quantity=VALUES(stock_quantity), active=VALUES(active);

-- 3. Khởi tạo lịch sử tồn kho (INITIAL_STOCK) tương ứng cho 100 sản phẩm mới
